import boto3

class DocumentClient:
    def __init__(self, region_name='us-west-2'):
        self.textract_client = boto3.client('textract', region_name=region_name)

    def start_document_analysis(self, document_bytes, feature_types=['FORMS', 'TABLES']):
        response = self.textract_client.start_document_analysis(
            Document={'Bytes': document_bytes},
            FeatureTypes=feature_types
        )
        return response

    def get_document_analysis_result(self, job_id):
        response = self.textract_client.get_document_analysis(JobId=job_id)
        return response

    def start_document_text_detection(self, document_bytes):
        response = self.textract_client.start_document_text_detection(
            Document={'Bytes': document_bytes}
        )
        return response

    def get_document_text_detection_result(self, job_id):
        response = self.textract_client.get_document_text_detection(JobId=job_id)
        return response

import boto3

def extract_key_values(document_path):
    textract_client = boto3.client('textract')
    with open(document_path, 'rb') as document:
        image_bytes = document.read()
    response = textract_client.analyze_document(
        Document={'Bytes': image_bytes},
        FeatureTypes=['FORMS'])
    key_values = {}
    for block in response['Blocks']:
        if block['BlockType'] == 'KEY_VALUE_SET':
            for relationship in block['Relationships']:
                if relationship['Type'] == 'CHILD':
                    child_ids = [child_id['Id'] for child_id in relationship['Ids']]
                    child_blocks = [block for block in response['Blocks'] if block['Id'] in child_ids]
                    key = next((block for block in child_blocks if block['BlockType'] == 'WORD' and block['Text'].lower() == 'key'), None)
                    value = next((block for block in child_blocks if block['BlockType'] == 'WORD' and block['Text'].lower() == 'value'), None)
                    if key and value:
                        key_values[key['Text']] = value['Text']
    return key_values

import boto3

def extract_text(image_bytes):
    textract_client = boto3.client('textract')
    response = textract_client.detect_document_text(Document={'Bytes': image_bytes})
    text = ''
    for item in response['Blocks']:
        if item['BlockType'] == 'LINE':
            text += item['Text'] + ' '
    return text.strip()
